#include <stdarg.h>
#include <stdio.h>
#include <wchar.h>

static int format(wchar_t *buf, size_t n, const wchar_t *fmt, ...) {
  va_list args;
  va_start(args, fmt);
  int len = vswprintf(buf, n, fmt, args);
  va_end(args);
  return len;
}

int main(void) {
  wchar_t buf[32];
  if (format(buf, 32, L"%ls #%d", L"item", 4) < 0) return 1;
  wprintf(L"%ls\n", buf);
  return 0;
}

